// Author: MiYu. Verify source reinforced defenses through live research and damage.
#include "session.h"
#include "setup.h"
#include "map_ui.h"
#include <algorithm>
#include <array>
#include <bit>
#include <cmath>
#include <iostream>
#include <sstream>
#include <string_view>

using namespace war3;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
void custom(ScriptSession& session,Archives& archives){
    auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto type=[&](const char* name){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(name)));};auto p0=call("Player",{vm.integer(0)}),p1=call("Player",{vm.integer(1)});auto bounds=session.world()->bounds();float x=std::bit_cast<float>(bounds.minX.bits())+512,y=std::bit_cast<float>(bounds.minY.bits())+512;unsigned offset=0;auto spawn=[&](const char* code,jass::Value owner){auto unit=call("CreateUnit",{owner,type(code),vm.real(real(x+192.f*float(offset++))),vm.real(real(y)),vm.real(real(0))});require(session.units().contains(unit.bits),"Custom test unit creation failed");return unit;};
    auto burrow=spawn("otrb",p0),unrelated=spawn("owtw",p0),attacker=spawn("hfoo",p1);auto first=type("R0F1"),second=type("R0F2");require(session.researchInfo(ObjectData::code("R0F1"),1).maximum==2 && session.researchInfo(ObjectData::code("R0F1"),1).unsupported.empty() && session.researchInfo(ObjectData::code("R0F2"),1).unsupported.empty(),"Custom defense upgrades unavailable");
    SourceSettings settings;settings.load(archives,"Units\\MiscData.txt");settings.load(archives,"Units\\MiscGame.txt");if(auto overlay=archives.readCandidates({"war3mapMisc.txt"},ArchiveScope::Map))settings.parse(overlay->bytes);std::stringstream source(settings.value("Misc","DamageBonusMagic"));std::array<float,8> factors{};for(auto& factor:factors){std::string value;require(bool(std::getline(source,value,',')),"Missing source magic factors");factor=std::stof(value);}for(unsigned a=2;a<=5;++a)for(unsigned b=a+1;b<=5;++b)require(std::abs(factors[a]-factors[b])>.01f,"Custom test source factors are not distinct");
    auto expect=[&](jass::Value target,unsigned armor){auto unit=session.units().at(target.bits);unit->life=unit->maxLife;float dealt=0;require(session.damageUnit(attacker.bits,target.bits,100,4,5,true,false,&dealt) && std::abs(dealt-100*factors[armor])<.1f,"Custom defense multiplier differed");};auto set=[&](jass::Value owner,jass::Value tech,int level){call("SetPlayerTechResearched",{owner,tech,vm.integer(level)});};expect(burrow,2);set(p0,first,1);expect(burrow,3);set(p0,second,1);expect(burrow,4);set(p0,first,2);expect(burrow,5);set(p0,first,2);set(p0,second,1);set(p0,first,0);expect(burrow,5);expect(unrelated,2);auto created=spawn("otrb",p0);expect(created,5);set(p1,first,1);call("SetUnitOwner",{burrow,p1,vm.boolean(false)});expect(burrow,3);call("SetUnitOwner",{burrow,p0,vm.boolean(false)});expect(burrow,5);require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS custom_defense_levels_stacking_and_owner_refresh\n";
}
}
int wmain(int argc,wchar_t** argv){try{
    if(argc!=3 && (argc!=4 || std::wstring_view(argv[3])!=L"custom"))throw std::runtime_error("Usage: war3_fortified_tests <data-root> <map> [custom]");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();if(argc==4){custom(session,archives);return 0;}auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto type=[&](const char* name){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(name)));};auto p0=call("Player",{vm.integer(0)}),p1=call("Player",{vm.integer(1)});auto bounds=session.world()->bounds();float x=std::bit_cast<float>(bounds.minX.bits())+512,y=std::bit_cast<float>(bounds.minY.bits())+512;unsigned offset=0;auto spawn=[&](const char* code,jass::Value player){auto result=call("CreateUnit",{player,type(code),vm.real(real(x+float(offset++%8)*192)),vm.real(real(y+float(offset/8)*192)),vm.real(real(0))});require(session.units().contains(result.bits),"Unit creation failed");return result;};
    auto mill=spawn("ofor",p0);spawn("ostr",p0);spawn("ofrt",p0);for(unsigned state:{1u,2u,4u,6u})call("SetPlayerState",{p0,vm.handle("playerstate",state),vm.integer(state<4?100000:1000)});auto burrow=spawn("otrb",p0),tower=spawn("owtw",p0),barricade=spawn("ocbw",p0),unrelated=spawn("hbar",p0),attacker=spawn("hfoo",p1);auto tech=ObjectData::code("Rorb");require(session.researchInfo(tech,1).unsupported.empty(),"Reinforced defenses remain unsupported");
    SourceSettings settings;settings.load(archives,"Units\\MiscData.txt");settings.load(archives,"Units\\MiscGame.txt");if(auto overlay=archives.readCandidates({"war3mapMisc.txt"},ArchiveScope::Map))settings.parse(overlay->bytes);std::stringstream source(settings.value("Misc","DamageBonusNormal"));std::array<float,8> factors{};for(auto& factor:factors){std::string value;require(bool(std::getline(source,value,',')),"Missing source damage factor");factor=std::stof(value);}require(std::abs(factors[2]-factors[3])>.01f,"Source armor factors are indistinguishable");
    auto damage=[&](jass::Value target){auto u=session.units().at(target.bits);u->life=u->maxLife;float dealt=0;require(session.damageUnit(attacker.bits,target.bits,100,1,5,true,false,&dealt),"Damage was rejected");return dealt;};auto expect=[&](jass::Value target,float factor){require(std::abs(damage(target)-100*factor)<.1f,"Damage did not use expected source defense type");};for(auto target:{burrow,tower,barricade})expect(target,factors[2]);auto untouched=damage(unrelated);
    require(session.research(mill.bits,tech),"Reinforced defenses research was rejected");auto producer=session.units().at(mill.bits);require(!producer->production.empty() && producer->production.front().research,"Research did not enter the production queue");producer->production.front().elapsed=producer->production.front().duration;session.advance(1./32);for(auto target:{burrow,tower,barricade})expect(target,factors[3]);require(std::abs(damage(unrelated)-untouched)<.1f,"Research changed an unrelated unit");std::cout<<"PASS researched_existing_structures_and_damage\n";
    auto created=spawn("otrb",p0);expect(created,factors[3]);call("SetUnitOwner",{created,p1,vm.boolean(false)});expect(created,factors[2]);call("SetUnitOwner",{created,p0,vm.boolean(false)});expect(created,factors[3]);require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS new_structure_and_ownership_refresh\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
